import React, { useState, useEffect } from "react";
import { Room, RoomMember, MatrixClient, MatrixError } from "matrix-js-sdk";
import { PillType } from "../components/views/elements/Pill";
import { MatrixClientPeg } from "../../MatrixClientPeg";
import { _t } from "../../i18n/sync";
import Avatar from "../components/views/elements/Avatar";
import { ButtonEvent } from "matrix-js-sdk";

interface HookResult {
    avatar: React.ReactElement | null;
    text: string | null;
    onClick: ((e: ButtonEvent) => void) | null;
    resourceId: string | null;
    type: PillType | "space" | null;
}

export function usePermalink(args: { room?: Room, type?: PillType, url?: string }): HookResult {
    const { room, type, url } = args;
    const [result, setResult] = useState<HookResult>({
        avatar: null,
        text: null,
        onClick: null,
        resourceId: null,
        type: null,
    });

    useEffect(() => {
        let cancelled = false;

        (async () => {
            const client = MatrixClientPeg.get();
            if (!client) {
                return;
            }

            let effectiveType = type;
            let resourceId: string | null = null;
            let text: string | null = null;
            let avatar: React.ReactElement | null = null;
            let onClick: ((e: ButtonEvent) => void) | null = null;

            if (url) {
                if (url.startsWith("@")) {
                    effectiveType = PillType.UserMention;
                    resourceId = url;
                } else if (url.startsWith("!") || url.startsWith("#")) {
                    effectiveType = PillType.RoomMention;
                    resourceId = url;
                }
            }

            if (effectiveType === PillType.AtRoomMention) {
                text = "@room";
                if (room) {
                    avatar = React.createElement(Avatar, {
                        room: room,
                        size: 16,
                        shape: "circular",
                        src: room?.mxcAvatar,
                    });
                }
            } else if (effectiveType === PillType.UserMention && resourceId) {
                const member = room?.getMember(resourceId);
                if (member) {
                    text = member.displayName || resourceId;
                    if (member.avatarUrl) {
                        avatar = React.createElement(Avatar, {
                            userId: resourceId,
                            size: 16,
                            shape: "circular",
                            src: member.avatarUrl,
                        });
                    }
                    onClick = (e: ButtonEvent) => {
                        client.viewUser(resourceId);
                    };
                } else {
                    text = resourceId;
                }
            } else if (effectiveType === PillType.RoomMention && resourceId) {
                const r = client.getRoom(resourceId) || (resourceId.startsWith("#") ? client.getRoom(resourceId) : null);
                if (r) {
                    text = r.name || resourceId;
                    if (r.mxcAvatar) {
                        avatar = React.createElement(Avatar, {
                            room: r,
                            size: 16,
                            shape: "circular",
                            src: r.mxcAvatar,
                        });
                    }
                } else {
                    text = resourceId;
                }
            }

            if (!cancelled) {
                setResult({
                    avatar,
                    text,
                    onClick,
                    resourceId,
                    type: effectiveType,
                });
            }
        })();

        return () => {
            cancelled = true;
        };
    }, [room, type, url]);

    return result;
}
>>>>>>> REPLACE
